From a0295dfa34e99ec3de756036abba9a3faea9af72 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:42:21 +0100
Subject: [PATCH] openvpn: Store the first part of a password that is asked
 every time

Passwords made of a fixed part and a one-time code from a token had to
be typed in full on every connection. "Ask for this password every
time" now stores what is typed in its field and fills it in when asking.

BUG: 388516
---
 kded/secretagent.cpp                  | 25 ++++++++++++++++++++++
 kded/secretagent.h                    |  1 +
 libs/editor/connectioneditorbase.cpp  |  3 ++-
 libs/editor/widgets/passwordfield.cpp | 30 ++++++++++++++++++++++++++-
 libs/editor/widgets/passwordfield.h   |  7 +++++++
 vpn/openvpn/openvpnauth.cpp           |  5 +++++
 vpn/openvpn/openvpnwidget.cpp         | 13 +++++++++---
 7 files changed, 79 insertions(+), 5 deletions(-)

diff --git a/kded/secretagent.cpp b/kded/secretagent.cpp
index 689c0d2da..1ab5b4d76 100644
--- a/kded/secretagent.cpp
+++ b/kded/secretagent.cpp
@@ -13,9 +13,11 @@

 #include "configuration.h"

+#include <NetworkManagerQt/ActiveConnection>
 #include <NetworkManagerQt/ConnectionSettings>
 #include <NetworkManagerQt/GenericTypes>
 #include <NetworkManagerQt/GsmSetting>
+#include <NetworkManagerQt/Manager>
 #include <NetworkManagerQt/Security8021xSetting>
 #include <NetworkManagerQt/Settings>
 #include <NetworkManagerQt/VpnSetting>
@@ -420,6 +422,21 @@ bool SecretAgent::processGetSecrets(QSharedPointer<SecretsRequest> request)
         }
     }

+    if (isVpn && !allowInteraction && isActivating(connectionSettings->uuid())) {
+        // A stored secret that is also flagged as not saved is only the first part of the password,
+        // so leave it out and let NetworkManager ask again with the dialog, where it gets filled in
+        auto vpnSetting = setting.staticCast<NetworkManager::VpnSetting>();
+        const NMStringMap data = vpnSetting->data();
+        NMStringMap secrets = vpnSetting->secrets();
+        for (const QString &key : vpnSetting->secrets().keys()) {
+            const auto flags = static_cast<NetworkManager::Setting::SecretFlags>(data.value(key + QLatin1String("-flags")).toInt());
+            if (flags.testFlag(NetworkManager::Setting::AgentOwned) && flags.testFlag(NetworkManager::Setting::NotSaved)) {
+                secrets.remove(key);
+            }
+        }
+        vpnSetting->setSecrets(secrets);
+    }
+
     if (!Configuration::self().showPasswordDialog()) {
         sendError(SecretAgent::NoSecrets, QStringLiteral("Cannot authenticate"), request->message);
         Q_EMIT secretsError(request->connection_path.path(),
@@ -581,6 +598,14 @@ bool SecretAgent::processDeleteSecrets(QSharedPointer<SecretsRequest> request)
     return true;
 }

+bool SecretAgent::isActivating(const QString &uuid) const
+{
+    const auto activeConnections = NetworkManager::activeConnections();
+    return std::any_of(activeConnections.cbegin(), activeConnections.cend(), [&uuid](const NetworkManager::ActiveConnection::Ptr &active) {
+        return active->uuid() == uuid && active->state() == NetworkManager::ActiveConnection::Activating;
+    });
+}
+
 bool SecretAgent::useSecureStorage() const
 {
     return QKeychain::isAvailable();
