diff --git a/libs/editor/connectioneditorbase.cpp b/libs/editor/connectioneditorbase.cpp
index 347356b76..868d2651a 100644
--- a/libs/editor/connectioneditorbase.cpp
+++ b/libs/editor/connectioneditorbase.cpp
@@ -467,7 +467,8 @@ void ConnectionEditorBase::initialize()
                     for (const QString &key : vpnSetting->data().keys()) {
                         if (key.endsWith(QStringLiteral("-flags"))) {
                             NetworkManager::Setting::SecretFlagType secretFlag = (NetworkManager::Setting::SecretFlagType)vpnSetting->data().value(key).toInt();
-                            if (secretFlag == NetworkManager::Setting::None || secretFlag == NetworkManager::Setting::AgentOwned) {
+                            // Agent-owned secrets can also be flagged as not saved, when only their first part is stored
+                            if (secretFlag == NetworkManager::Setting::None || (secretFlag & NetworkManager::Setting::AgentOwned)) {
                                 requestSecrets = true;
                             }
                         }
diff --git a/libs/editor/widgets/passwordfield.cpp b/libs/editor/widgets/passwordfield.cpp
index 654f2a8b9..bc856658b 100644
--- a/libs/editor/widgets/passwordfield.cpp
+++ b/libs/editor/widgets/passwordfield.cpp
@@ -7,7 +7,9 @@
 #include "passwordfield.h"

 #include <QAction>
+#include <QEvent>
 #include <QIcon>
+#include <QTimer>

 #include <KAuthorized>
 #include <KLocalizedString>
@@ -113,6 +115,29 @@ void PasswordField::setPasswordNotRequiredEnabled(bool enable)
     }
 }

+void PasswordField::setPasswordPartlySavedEnabled(bool enable)
+{
+    m_partlySavedEnabled = enable;
+}
+
+void PasswordField::setCursorAtEndOnFocus(bool enable)
+{
+    m_cursorAtEndOnFocus = enable;
+    m_passwordField->installEventFilter(this);
+}
+
+bool PasswordField::eventFilter(QObject *watched, QEvent *event)
+{
+    if (m_cursorAtEndOnFocus && watched == m_passwordField && event->type() == QEvent::FocusIn) {
+        // QLineEdit selects all text when focused with Tab, and typing would then replace it
+        QTimer::singleShot(0, m_passwordField, [this]() {
+            m_passwordField->deselect();
+            m_passwordField->end(false);
+        });
+    }
+    return QWidget::eventFilter(watched, event);
+}
+
 void PasswordField::setText(const QString &text)
 {
     m_passwordField->setText(text);
@@ -158,12 +183,15 @@ void PasswordField::changePasswordOption(int index)

     m_currentPasswordOption = (PasswordOption)m_passwordOptionsMenu->currentData().toUInt();

+    // When partly saving is enabled, what is typed in for "Ask every time" is stored and filled in when asking
+    const bool partlySaved = m_partlySavedEnabled && m_currentPasswordOption == PasswordField::AlwaysAsk;
     if (m_currentPasswordOption == PasswordField::NotRequired || m_currentPasswordOption == PasswordField::AlwaysAsk) {
         m_passwordField->clear();
-        m_passwordField->setDisabled(true);
+        m_passwordField->setDisabled(!partlySaved);
     } else {
         m_passwordField->setEnabled(true);
     }
+    m_passwordField->setPlaceholderText(partlySaved ? i18n("Optional: first part of the password, filled in every time") : QString());

     Q_EMIT passwordOptionChanged(m_currentPasswordOption);
 }
