@@ -318,7 +320,12 @@ void OpenVpnSettingWidget::handleOnePasswordType(const PasswordField *passwordFi
         data.insert(key, QString::number(NetworkManager::Setting::AgentOwned));
         break;
     case PasswordField::AlwaysAsk:
-        data.insert(key, QString::number(NetworkManager::Setting::NotSaved));
+        // The first part of the password, if given, is stored by the agent and filled in when asking
+        if (passwordField->text().isEmpty()) {
+            data.insert(key, QString::number(NetworkManager::Setting::NotSaved));
